<?php
namespace App\Http\Controllers;use App\Models\{RhAvenantContrat,RhContrat};use App\Services\{AuditLogService,CurrentEntreprise,RhContractNumberService};use Illuminate\Http\Request;
class RhAvenantContratController extends Controller{public function store(Request $r,RhContrat $contrat,RhContractNumberService $nums,CurrentEntreprise $c){abort_unless((int)$contrat->entreprise_id===(int)$c->for()->id,404);$d=$r->validate(['date_effet'=>'required|date|after_or_equal:'.$contrat->date_debut->toDateString(),'motif'=>'required|string|min:3','nouvelles_valeurs'=>'required|array','nouvelles_valeurs.salaire_base'=>'nullable|numeric|min:0','nouvelles_valeurs.date_fin'=>'nullable|date','nouvelles_valeurs.poste'=>'nullable|string','nouvelles_valeurs.primes_fixes'=>'nullable|numeric|min:0']);$anciennes=array_intersect_key($contrat->toArray(),$d['nouvelles_valeurs']);$a=RhAvenantContrat::create($d+['entreprise_id'=>$contrat->entreprise_id,'contrat_id'=>$contrat->id,'numero'=>$nums->avenant($contrat->entreprise_id,(int)date('Y',strtotime($d['date_effet']))),'date_creation'=>today(),'anciennes_valeurs'=>$anciennes,'cree_par'=>$r->user()->id,'statut'=>'Brouillon']);app(AuditLogService::class)->record('creation_avenant_rh',$a,$a->numero,$d['motif'],null,$a->toArray(),[],$r);return back()->with('success','Avenant '.$a->numero.' créé.');}public function valider(Request $r,RhAvenantContrat $avenant,CurrentEntreprise $c){abort_unless((int)$avenant->entreprise_id===(int)$c->for()->id,404);abort_unless($avenant->statut==='Brouillon',422);$old=$avenant->toArray();$avenant->update(['statut'=>'Validé','valide_par'=>$r->user()->id,'valide_le'=>now()]);app(AuditLogService::class)->record('validation_avenant_rh',$avenant,$avenant->numero,$avenant->motif,$old,$avenant->fresh()->toArray(),[],$r);return back()->with('success','Avenant validé.');}}
